const backendURL = dataiku.getWebAppBackendUrl('');
window.addEventListener('load', function() {
    document.body.style.margin = '0';
    const ifrm = document.createElement('iframe');
    ifrm.setAttribute('src', backendURL + '?URL=' + backendURL);
    ifrm.setAttribute('style', 'position:fixed; top:0; left:0; bottom:0; right:0; width:100%; height:100%; border:none; margin:0; padding:0; overflow:hidden;');
    document.body.replaceChildren(ifrm);
});
